package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class NotificationsActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Notifications","Important updates from your AcreNex workspace.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT title,message,type,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC",new String[]{uid});try{if(!c.moveToFirst())root.addView(utils.text(this,"No new notifications.",15,0xff71808f,false));else do{LinearLayout box=utils.column(this);utils.row(box,this,"Type",c.getString(2));utils.row(box,this,"Title",c.getString(0));box.addView(utils.text(this,c.getString(1),14,0xff183b56,false));box.addView(utils.text(this,c.getString(3),12,0xff71808f,false));utils.addCard(root,box,this);}while(c.moveToNext());}finally{c.close();}utils.setScreenContentView(this, root);}
}
